.venv/bin/python - <<'EOF'
import sys
sys.path.insert(0,'docs/features/sequencias-customizadas')
import research_compare as rc

def match_legado(song, chords):
    vocab_ok = set(song['acordes']) <= set(chords)
    return vocab_ok and rc.match_contiguous(song, chords)

songs=rc.load()
print('%-10s %-6s %-6s %-6s %-6s'%('seq','tag','legado','faltam','extras'))
for key,(i,ch) in rc.SEQUENCIAS.items():
    tag={s['id'] for s in songs if rc.match_tag(s,i)}
    leg={s['id'] for s in songs if match_legado(s,ch)}
    print('%-10s %-6d %-6d %-6d %-6d'%(key,len(tag),len(leg),len(tag-leg),len(leg-tag)))
    for sid in list(leg-tag)[:3]:
        s=next(x for x in songs if x['id']==sid)
        print('   legado-only',sid,s['cifra'][:14],'tag=',s['seqs_famosas'])
EOF

